  "Adds bodycams to the register and updates the ones already there, matched by serial number. Who has a bodycam right now never changes by import; that happens only when it is booked out or handed back.": "E oketsa dikhamera tsa mmele mo rejisetareng mme e ntšhafatsa tse di setseng di le teng, ka go tshwantshanya nomore ya serial. Yo o tshwereng khamera ya mmele jaanong ga a fetoge ka go tsenya; seo se diragala fela fa e ntshiwa kgotsa e busiwa.",
  "Adds firearms to the register and updates the ones already there, matched by serial number. Who holds a firearm right now never changes by import; that happens only when it is booked out or handed back.": "E oketsa ditlhobolo mo rejisetareng mme e ntšhafatsa tse di setseng di le teng, ka go tshwantshanya nomore ya serial. Yo o tshwereng sethunya jaanong ga a fetoge ka go tsenya; seo se diragala fela fa se ntshiwa kgotsa se busiwa.",
  "Adds people to the staff register and updates the ones already there, matched by badge number. Nobody gets access: each person is invited afterwards and activates their own account.": "E oketsa batho mo rejisetareng ya badiri mme e ntšhafatsa ba ba setseng ba le teng, ka go tshwantshanya nomore ya beche. Ga go ope yo o bonang phitlhelelo: motho mongwe le mongwe o a laletswa morago mme a bule akhaonto ya gagwe.",
  "Adds vehicles to the register and updates the ones already there, matched by department and unit number. A vehicle’s status never changes by import: one off the road stays off the road until fleet control returns it.": "E oketsa dikoloi mo rejisetareng mme e ntšhafatsa tse di setseng di le teng, ka go tshwantshanya lefapha le nomore ya yuniti. Maemo a koloi ga a fetoge ka go tsenya: e e seng mo tseleng e nna e se mo tseleng go fitlhelela taolo ya dikoloi e e busa.",
