  "EMERGENCY MEDICAL SERVICES": "DITIRELO TSA TSHOGANYETSO TSA KALAFI",
  "EMERGENCY MEDICAL SERVICES · DOCTOR": "DITIRELO TSA TSHOGANYETSO TSA KALAFI · NGAKA",
  "EMERGENCY MEDICAL SERVICES · START OF SHIFT": "DITIRELO TSA TSHOGANYETSO TSA KALAFI · TSHIMOLOGO YA ŠIFITI",
