  "ETCO2": "ETCO2",
  "EVIDENCE ({n})": "BOSUPI ({n})",
  "Each call sign is a row: pick the member for it.": "Letshwao lengwe le lengwe la go bitsa ke mola: tlhopha leloko la lona.",
  "Each call sign is one duty slot: where it patrols, its hours, its break and the rank it needs. Duty Allocation books staff onto these.": "Letshwao lengwe le lengwe la go bitsa ke sebaka se le sengwe sa tiro: kwa le patrolang teng, diura tsa lona, boikhutso jwa lona le maemo a le a tlhokang. Kabo ya Tiro e beakanya badiri mo go tsona.",
  "Each call sign with its area, hours and the rank it needs.": "Letshwao lengwe le lengwe la go bitsa le lefelo la lona, diura le maemo a le a tlhokang.",
  "Each day's reports, by where they stand.": "Dipego tsa letsatsi lengwe le lengwe, go ya ka kwa di emeng teng.",
  "Each link or code works once and expires after {invitationTtlHours} hours. Sending again cancels the old one.": "Kgolagano kgotsa khoutu nngwe le nngwe e dira gangwe mme e fela morago ga diura di le {invitationTtlHours}. Go romela gape go phimola e kgologolo.",
  "Each member’s record as the old system kept it: numbers, rank, station, section, weekend group, contacts, LEO record and screen access.": "Rekoto ya leloko lengwe le lengwe jaaka thulaganyo e kgologolo e e bolokileng: dinomoro, maemo, seteišene, karolo, setlhopha sa beke-bosheng, bagolagani, rekoto ya LEO le phitlhelelo ya sekerine.",
  "Each patient and how bad they are": "Molwetse mongwe le mongwe le gore o mo maemong a a maswe go le kae",
  "Each person gets their own invitation, as their confirmed role, by the route shown: email where HR gave an address, SMS where there is only a cellphone{value}, otherwise a printed code. Each link or code works once and expires after its set time.": "Motho mongwe le mongwe o bona taletso ya gagwe, jaaka tiro ya gagwe e e netefaditsweng, ka tsela e e bontshitsweng: imeile kwa HR e neileng aterese, SMS kwa go nang le sele fela{value}, fa go se jalo khoutu e e gatisitsweng. Kgolagano kgotsa khoutu nngwe le nngwe e dira gangwe mme e fela morago ga nako ya yone e e beilweng.",
  "Each rule acts at most once per thing per threshold — a call that breaches its SLA raises one alert at each tier, not one every five minutes. Thresholds are stored per rule, so changing “escalate after 10 minutes” to 15 needs no deployment. Every change and every manual run is written to the audit trail with your name on it.": "Molao mongwe le mongwe o dira gangwe fela mo selong sengwe le sengwe mo selekanyong sengwe le sengwe — mogala o o fetang SLA ya one o tsosa tlhagiso e le nngwe mo maemong mangwe le mangwe, e seng e le nngwe metsotso e mengwe le e mengwe e le tlhano. Ditekanyo di bolokwa ka molao mongwe le mongwe, ka jalo go fetola \"oketsa morago ga metsotso e le 10\" go nna 15 ga go tlhoke go tsenngwa. Phetogo nngwe le nngwe le go dira gongwe le gongwe ka seatla go kwalwa mo motlhaleng wa tlhatlhobo le leina la gago.",
  "Each service's identity — crest, colours and naming — as it appears across the platform, the responder app and printed reports.": "Boitshupo jwa tirelo nngwe le nngwe — letshwao, mebala le maina — jaaka bo bonala mo seraleng sotlhe, mo app ya batsibogi le mo dipegong tse di gatisitsweng.",
