  "Emergency lights & siren functioning": "Mabone a tshoganyetso le seirene di a dira",
  "Emergency — hold to call for assistance": "Tshoganyetso — tshwara go kopa thuso",
  "Emergency-flagged rows are highlighted. Resolve inline once handled.": "Mela e e tshwailweng jaaka tshoganyetso e a bonatswa. E rarabolole fano fa e setse e tlhokometswe.",
  "Emotional Wellbeing (Feeling mentally balanced?)": "Boitekanelo jwa maikutlo (A o ikutlwa o lekalekane mo tlhaloganyong?)",
  "Employee": "Mmereki",
  "Employee name": "Leina la mmereki",
  "Employment status": "Maemo a tiro",
  "Emulators and simulators cannot register for push. Alerts still arrive while the app is open.": "Di-emulator le di-simulator ga di kgone go ikwadisetsa dikitsiso. Ditlhagiso di sa ntse di tla fa app e butswe.",
  "En Route": "O mo tseleng",
  "En route": "O mo tseleng",
  "Enabled": "Go butswe",
  "Enabling a feature never grants a role anything the route matrix and row-level security would not — the two systems compose. Disabling one hides it everywhere and makes its server routes refuse, for this tenant only.": "Go bula sengwe ga go neye tiro sepe se matrix ya ditsela le pabalesego ya maemo a mola di neng di ka se se letle — ditsamaiso tse pedi di dira mmogo. Go tima nngwe go e fitlha gongwe le gongwe mme go dira gore ditsela tsa yone tsa sebele di gane, mo mohiring ono fela.",
  "End": "Bofelo",
