  "End your shift and go off duty.": "Fetsa šifiti ya gago mme o tswe mo tirong.",
  "Ending a shift in the app is not switched on for this server yet. Hand your kit in at the counter and tell your supervisor.": "Go fetsa šifiti ka app ga go ise go bulwe mo sebeleng seno. Neela didirisiwa tsa gago kwa khaontareng mme o bolelele molaodi wa gago.",
