  "For Disaster Management": "Go Taolo ya Maswe",
  "For Fire & Rescue": "Go Molelo le Phatlhaselo",
  "For a call that will never have a report: a hoax, a duplicate, or the caller cancelled.{value}": "Mogala o o ka se keng wa nna le pego: maaka, o o boeleditsweng, kgotsa moletsi o khansetse.{value}",
  "For a notice issued in error. It stays on the register, marked cancelled, with your reason. Refund any money first.": "Kitsiso e e ntshitsweng ka phoso. E nna mo rejisetareng, e tshwailwe e le e e khansetsweng, le lebaka la gago. Busetsa madi mangwe le mangwe pele.",
  "For a notice written in a notice book. Copy it exactly as written, with the printed notice number. Notices at the roadside are issued on the phone, where the infringer signs.": "Kitsiso e e kwadilweng mo bukeng ya dikitsiso. E kopolole jaaka e kwadilwe, le nomoro ya kitsiso e e gatisitsweng. Dikitsiso tsa mo tseleng di ntshiwa mo mogaleng, kwa motlodi a saenang teng.",
  "For example towards the taxi rank": "Sekai, go lebagana le lefelo la ditekesi",
  "For example: radio from a security guard": "Sekai: radio e e tswang mo molebeling wa pabalesego",
  "For example: the caller rang back with the right address": "Sekai: moletsi o leleditse gape ka aterese e e siameng",
  "For leave on a form the member handed in, sick leave, or an absence such as AWOL. It is approved as captured and their duty in those dates is marked.": "Go boikhutso mo foromong e leloko le e tsentseng, boikhutso jwa bolwetse, kgotsa go sa nne gona jaaka AWOL. Bo amogelwa jaaka bo tsentswe mme tiro ya bona mo malatsing ao e tshwaiwa.",
  "For the whole organisation. Office-hours rotations skip them, and they are not counted as leave days.": "Ya mokgatlho otlhe. Go fetofetoga ga diura tsa kantoro go a di tlola, mme ga di balwe jaaka malatsi a boikhutso.",
  "For their shift": "Ya shifi ya bone",
  "For you, your role, your department and everyone.": "Ya gago, ya tiro ya gago, ya lefapha la gago le ya botlhe.",
