  "How often this rule is evaluated. The scheduler ticks every 5 minutes, so anything below that runs every tick.": "Gore molao o o tlhatlhobiwa ga kae. Sethulaganyi se dira metsotso nngwe le nngwe e le 5, ka jalo sengwe le sengwe se se kwa tlase ga moo se dira nako nngwe le nngwe.",
