  "I am at the scene": "Ke kwa lefelong",
  "I am not drawing a firearm this shift (e.g. mine is not on the armoury register). This is recorded on my start-of-shift record.": "Ga ke tseye tlhobolo mo shifing eno (sk. ya me ga e mo rejisetareng ya ntlo ya dibetsa). Se se kwadilwe mo rekotong ya me ya go simolola shifi.",
  "I am not wearing a bodycam this shift. My reason is on my start-of-shift record and my supervisor sees it.": "Ga ke apare khamera ya mmele mo shifing eno. Lebaka la me le mo rekotong ya me ya go simolola shifi mme mookamedi wa me o a le bona.",
  "I checked this ambulance and its stock myself, and the answers above are accurate.": "Ke tlhatlhobile ambulense eno le thoto ya yone ka bonna, mme dikarabo tse di fa godimo di nepagetse.",
  "I confirm that I have physically inspected the above vehicle and that the information recorded is accurate to the best of my knowledge. Any faults noted must be reported to the immediate supervisor and recorded in the official pocket book.": "Ke netefatsa gore ke tlhatlhobile koloi e e fa godimo ka mmele mme tshedimosetso e e kwadilweng e nepagetse go ya ka kitso ya me. Diphoso dipe tse di lemogilweng di tshwanetse go begelwa mookamedi wa gaufi mme di kwalwe mo bukeng ya semmuso ya kgetsana.",
  "I explained the court date, and that paying the admission of guilt is a conviction and may give a criminal record.": "Ke tlhalositse letlha la kgotlatshekelo, le gore go duela faene ya go ipona molato ke go atlholwa mme go ka naya rekoto ya bosenyi.",
  "I explained the notice and the options: pay within 32 days for the discount, apply to pay in instalments (AARTO 04), or make a representation (AARTO 08).": "Ke tlhalositse kitsiso le ditlhopho: duela mo malatsing a le 32 go bona phokotso, dira kopo ya go duela ka dikarolo (AARTO 04), kgotsa o dire boemedi (AARTO 08).",
  "I have an activation code": "Ke na le khoutu ya go simolola",
  "I have read the POPIA notice (version {POPIA_NOTICE_VERSION})": "Ke badile kitsiso ya POPIA (kgatiso {POPIA_NOTICE_VERSION})",
  "I have read this shift": "Ke badile se mo shifing eno",
  "I know how your department works and I can read the live board your role can see. Ask me anything, or tell me what to do. I prepare it, and nothing changes until you confirm.": "Ke itse ka fa lefapha la gago le dirang ka teng mme nka bala boto ya nako eo tiro ya gago e ka e bonang. Mpotsa sepe fela, kgotsa o mpolelele se ke tshwanetseng go se dira. Ke a se baakanya, mme ga go sepe se se fetogang go fitlha o netefatsa.",
  "I know your shift, your calls, your leave and your kit. Ask me anything about your work, in your own words. I explain and show you where to go; you do the work.": "Ke itse šifiti ya gago, megala ya gago, khunologo ya gago le didirisiwa tsa gago. Mpotsa sengwe le sengwe ka tiro ya gago, ka mafoko a gago. Ke a tlhalosa le go go bontsha kwa o tshwanetseng go ya teng; wena o dira tiro.",
  "I personally completed these checks and confirm that the answers and any defects recorded are accurate.": "Ke weditse ditlhatlhobo tseno ka bonna mme ke netefatsa gore dikarabo le diphoso dipe tse di kwadilweng di nepagetse.",
  "I will use HikTech only for official duties and keep my password private": "Ke tla dirisa HikTech mo ditirong tsa semmuso fela mme ke boloke lefoko la me la sephiri le le sephiri",
