  "Incidents routed to your department reach this phone even when the screen is locked. High and Critical incidents open a full-screen alert you must acknowledge.": "Ditiragalo tse di romelwang kwa lefapheng la gago di fitlha mo mogaleng ono le fa sekirini se lotlegile. Ditiragalo tse di Kwa godimo le tse di Masisi di bula tlhagiso ya sekirini sotlhe e o tshwanetseng go e amogela.",
