  "Isuzu": "Isuzu",
  "It gets the next CH- number; the arresting officer is you unless noted.": "E bona nomoro e e latelang ya CH-; mopodisi yo o tshwarang ke wena fa e se fa go supilwe ka tsela e nngwe.",
  "It gets the next DM- number; the assignee is alerted at once.": "E bona nomoro e e latelang ya DM-; yo o abetsweng o itsisiwe ka bonako.",
  "It gets the next SM- number. Service is recorded from the register below.": "E bona nomoro e e latelang ya SM-. Tirelo e kwalwa go tswa mo rejisetareng e e fa tlase.",
  "It gets the next WA- number. Court and expiry as issued.": "E bona nomoro e e latelang ya WA-. Kgotlatshekelo le go fela ga nako jaaka di ntshitswe.",
  "It goes for repair and your supervisor is told.": "E ya go baakangwa mme mookamedi wa gago o a itsisiwe.",
  "It goes to the armourer for repair instead of back into service.": "E ya kwa mmaakanying wa dibetsa go baakangwa go na le go boela tirelong.",
  "It is alleged that…": "Go tlhalosiwa gore…",
  "It is held on this phone and sends automatically, ahead of everything else, the moment you have signal. Do not wait — SMS or call the control room now.": "E bolokilwe mo mogaleng ono mme e romelwa ka boyone, pele ga sengwe le sengwe se sele, ka bonako fa o na le kgolagano. O se ka wa ema — romela SMS kgotsa o leletse phaposi ya taolo jaanong.",
  "It is in the description, and follows your answers until you type.": "E mo tlhalosong, mme e latela dikarabo tsa gago go fitlha o tlanya.",
  "It is waiting for signal and sends automatically.": "E emetse kgolagano mme e tla romelwa ka boyone.",
  "It may belong to another officer, or the link is out of date.": "E ka nna ya mopodisi yo mongwe, kgotsa kgolagano e fetilwe ke nako.",
  "It may have been closed or reassigned, or it is not for your department.": "E ka nna e tswetswe kgotsa e abetswe gape, kgotsa ga se ya lefapha la gago.",
  "It may have been reassigned, or you no longer have access to it.": "E ka nna e abetswe gape, kgotsa ga o sa na phitlhelelo go yone.",
  "It may have been reassigned.": "E ka nna e abetswe gape.",
  "It may not have reached the server yet.": "E ka nna e ise e fitlhe kwa sefaneleng.",
  "It prints on the duty sheet beside their name.": "E gatisiwa mo pampiring ya tiro gaufi le leina la bone.",
  "It resolves {incident_number} and becomes a permanent record — it cannot be edited or deleted afterwards.": "E rarabolola {incident_number} mme e nna rekoto ya ka metlha — e ka se fetolwe kgotsa ya phimolwa morago.",
  "It resolves {incident_number}.": "E rarabolola {incident_number}.",
  "It sends when you have signal.": "E romelwa fa o na le kgolagano.",
  "It stays on the record with your name and the reason.": "E nna mo rekotong le leina la gago le lebaka.",
  "It stays on this phone under your account and sends the next time you sign in with signal.": "E nna mo mogaleng ono ka fa tlase ga akhaonto ya gago mme e romelwa fa o tsena gape o na le kgolagano.",
  "It will go to maintenance, not back into service.": "E tla ya kwa tlhokomelong, e seng go boela tirelong.",
