  "Official After-Action Reports. Filing one resolves the incident.": "Dipego tsa Semmuso tsa Morago ga Tiro. Go romela nngwe go rarabolola tiragalo.",
  "Official insignia belong to the municipality and its services, so the platform ships none — upload each department's real crest here and it appears everywhere immediately. Until then a monogram badge renders in that department's colours, so nothing ever looks unfinished. PNG or SVG with a transparent background works best; square crops read cleanest at small sizes.": "Matshwao a semmuso ke a mmasepala le ditirelo tsa one, ka jalo sethala ga se a tlise — tsenya letshwao la nnete la lefapha lengwe le lengwe fano mme le tlhagelela gongwe le gongwe ka bonako. Go fitlha ka nako eo beche ya ditlhaka tsa ntlha e bontshiwa ka mebala ya lefapha leo, ka jalo ga go na sepe se se lebegang se sa fediwa. PNG kgotsa SVG e e nang le bokafatlhoko jo bo bonalang e dira botoka; ditshwantsho tsa sekwere di balega sentle fa di le dinnye.",
