  "On scene is set by the crew’s own phone reaching the scene. Click a strip to see the crew.": "Go nna kwa lefelong go tlhomiwa ke founu ya setlhopha ka bosone fa e goroga kwa lefelong. Tobetsa mola go bona setlhopha.",
