  "One at a time. For many, use the import with the template.": "Nngwe ka nako. Go tse dintsi, dirisa go tsenya ka thempoleite.",
  "One at a time. For the whole armoury, use the import with the template.": "Se le sengwe ka nako. Go polokelo yotlhe ya dibetsa, dirisa go tsenya ka thempoleite.",
