  "Only Staff Maintenance and the member can see this.": "Ke Tlhokomelo ya Badiri le leloko fela ba ba ka bonang se.",
  "Only a translator for this language approves. You can save drafts.": "Ke moranolodi wa puo eno fela yo o letlelelang. O ka boloka ditlhomo.",
  "Only approved translations are shown on the screens. Everything else shows in English.": "Diranolo tse di letlelelweng fela di bontshiwa mo dikiriining. Tse dingwe tsotlhe di bontshiwa ka Seesemane.",
  "Only fines I issued": "Dikotlhao tse ke di neileng fela",
  "Only if there is no emergency. Why?": "Fela fa go se na tshoganyetso. Ke ka ntlha yang?",
  "Only me": "Nna fela",
  "Only officers who went on duty in the app after today's start of shift are listed. Distance is straight-line from their last GPS heartbeat; ETA assumes {speedKmh} km/h with a {roadFactor}× road factor (Admin → Operations Settings).": "Go kwadiwa fela bahlankedi ba ba tsenang mo tirong ka app morago ga tshimologo ya šifiti ya gompieno. Sekgala ke mola o o tlhamaletseng go tswa mo seswaong sa bone sa bofelo sa GPS; ETA e tsaya {speedKmh} km/h le ntlha ya tsela ya {roadFactor}× (Admin → Dithulaganyo tsa Tiro).",
  "Only one patient": "Molwetse a le mongwe fela",
  "Only someone senior to the member, in their department, can approve. Nobody approves their own.": "Ke motho yo o kwa godimo ga leloko fela, mo lefapheng la lone, yo o ka letlelelang. Ga go na ope yo o itetlelelang.",
  "Only the firefighter leading this incident files its fire report.": "Ke morimamolelo yo o eteletseng tiragalo eno pele fela yo o romelang pego ya yone ya molelo.",
  "Only the lead officer on this incident can file its report.": "Ke mohlankedi yo o eteletseng tiragalo eno pele fela yo o ka romelang pego ya yone.",
