  "Only the paramedic leading this incident files its patient report.": "Ke paramediki yo o eteletseng tiragalo eno pele fela yo o romelang pego ya yone ya molwetse.",
  "Only the person who logged {number}, or the control room, can finish it.": "Ke motho yo o kwadileng {number} fela, kgotsa phaposi ya taolo, yo o ka e fetsang.",
