  "Road traffic offences carry the AARTO Schedule 3 charge code and penalty; by-law offences carry the by-law section and the admission of guilt amount. Enter both from the official schedules, then verify. Changing a verified code or amount takes the verification off until someone checks it again.": "Melato ya tsela e tshwere khoutu ya molato ya AARTO Schedule 3 le kotlhao; melato ya molao wa mmasepala e tshwere karolo ya molao le madi a go ipolela molato. Tsenya tsotlhe pedi go tswa mo mananeong a semmuso, mme o netefatse. Go fetola khoutu kgotsa madi a a netefaditsweng go tlosa netefatso go fitlha mongwe a e tlhatlhoba gape.",
  "Road traffic offences on AARTO 01 notices; by-law offences on Section 56 (offender present) or Section 341 (unattended vehicle) notices. Every charge has its own FN- number, and a served notice can never be edited or deleted — only cancelled, with a reason.": "Melato ya tsela mo dikitsisong tsa AARTO 01; melato ya molao wa mmasepala mo dikitsisong tsa Karolo 56 (motlolamolao o teng) kgotsa Karolo 341 (koloi e e sa tlhokomelweng). Molato mongwe le mongwe o na le nomore ya one ya FN-, mme kitsiso e e abilweng e ka se ke e fetolwa kgotsa ya phimolwa — e ka khanselwa fela, ka lebaka.",
