  "Secrets live in server environment variables and are never stored in the database or sent to the browser — this page only reports whether each one is present. The switch and the JSON parameters below are stored in the database and take effect immediately, with no redeploy. Adding or changing a secret requires setting it on the host and redeploying.": "Diphiri di nna mo diphetogong tsa tikologo ya seva mme ga di ke di bolokwa mo database kgotsa di romelwa kwa sefetlhing — tsebe eno e bega fela fa nngwe le nngwe e le teng. Sesupi le dipharamitha tsa JSON fa tlase di bolokwa mo database mme di dira ka bonako, kwa ntle ga go tsenya gape. Go oketsa kgotsa go fetola sephiri go tlhoka go se tlhoma mo go mothapi mme o tsenye gape.",
