  "Upload the day’s receipts from the cashier or the bank. Each row is matched to a fine by its FN- number or its notice number, and recorded with the date on the receipt — so a payment made inside the 32 days keeps the AARTO discount even when it is captured later. A receipt already on a fine is skipped, so importing the same file twice records nothing twice.": "Tsenya diresiti tsa letsatsi go tswa kwa mmolokamatlotlo kgotsa kwa bankeng. Mola mongwe le mongwe o tshwantshiwa le kotlhao ka nomore ya yone ya FN- kgotsa nomore ya kitsiso ya yone, mme o kwalwa le letlha le le mo resiting — ka jalo tuelo e e dirilweng mo teng ga malatsi a le 32 e boloka phokotso ya AARTO le fa e tsentswe morago. Resiti e e setseng e le mo kotlhaong e a tlolwa, ka jalo go tsenya faele e e tshwanang gabedi ga go kwale sepe gabedi.",
