  "What each tenant's portal offers, module by module — hide one for the whole organisation or deny it to specific roles. Rules only ever subtract from the built-in role matrix, and take effect everywhere within a minute.": "Se phothale ya mohiri mongwe le mongwe e se neelang, motšule ka motšule — fitlha nngwe mo mokgatlhong otlhe kgotsa o e ganele diseabe dingwe. Melao e tlosa fela mo lenaaneng la diseabe le le agilweng ka fa teng, mme e dira gongwe le gongwe mo motsotsong.",
