  "What is sent to you, your role, your department and everyone lands here. High and Critical incidents also open a full-screen alert you have to acknowledge.": "Se se romelwang kwa go wena, mo seabeng sa gago, mo lefapheng la gago le kwa go botlhe se goroga fano. Ditiragalo tse di Kwa Godimo le tse di Botlhokwa thata di bula gape tlhagiso ya sekirini sotlhe e o tshwanetseng go e amogela.",
  "What is switched on for {value}. Changes apply to every user in the organisation, take effect on their next page load — the responder app follows within moments over realtime — and are written to the audit trail with your name.": "Se se butsweng mo {value}. Diphetogo di dira mo badirising botlhe mo mokgatlhong, di simolola fa ba laisa tsebe e e latelang — app ya baarabi e latela mo metsotswaneng — mme di kwalwa mo motlhaleng wa tlhatlhobo ka leina la gago.",
