  "You are fit and ready to go now?": "A o itekanetse mme o siametse go tsamaya jaanong?",
  "You are leading": "O eteletse pele",
  "You are leading this incident": "O eteletse pele tiragalo eno",
  "You are not at the scene yet. The assessment is done on site; the draft is kept.": "Ga o ise o goroge kwa lefelong. Tlhatlhobo e dirwa kwa lefelong; tlhomo e bolokilwe.",
  "You are not on standby": "Ga o eme",
  "You are off duty": "Ga o mo tirong",
  "You are off duty — incidents are not sent to you. Tap to go on duty.": "Ga o mo tirong — ditiragalo ga di romelwe kwa go wena. Tobetsa go tsena mo tirong.",
  "You are off duty.": "Ga o mo tirong.",
  "You are off duty. Go on duty to respond to incidents.": "Ga o mo tirong. Tsena mo tirong go araba ditiragalo.",
  "You are on duty, but today’s start of shift could not be confirmed. Check your signal and try again.": "O mo tirong, mme tshimologo ya šifiti ya gompieno ga e a kgona go netefadiwa. Tlhatlhoba kgolagano ya gago mme o leke gape.",
  "You are on the air. Let go to listen.": "O mo moweng. Tlogela go reetsa.",
  "You are on {incident_number}": "O mo {incident_number}",
  "You are still on {incident_number}. File its {report} before you end your shift.": "O sa ntse o le mo {incident_number}. Romela {report} ya yone pele o fetsa šifiti ya gago.",
  "You cannot change your own account. Ask another administrator.": "O ka se fetole akhaonto ya gago. Kopa motsamaisi yo mongwe.",
  "You cannot deactivate your own account.": "O ka se time akhaonto ya gago.",
  "You cannot go on standby. Speak to your supervisor, then retake the check.": "O ka se eme. Bua le motsamaisi wa gago, mme o boeletse tlhatlhobo.",
  "You go off duty and stop receiving dispatches.": "O tswa mo tirong mme o tlogela go amogela tse di romelwang.",
  "You go on duty once your checks are complete.": "O tsena mo tirong fa ditlhatlhobo tsa gago di weditswe.",
  "You have arrived": "O gorogile",
  "You have no duty office screens yet. Ask the systems controller for access.": "Ga o ise o nne le dikiriini tsa ofisi ya tiro. Kopa motsamaisi wa ditsamaiso phitlhelelo.",
  "You have not applied for leave yet.": "Ga o ise o dire kopo ya khunologo.",
  "You have not been placed on duty. Your answers were saved for supervisor review. Speak to your supervisor, then retake the check when your situation changes.": "Ga o a bewa mo tirong. Dikarabo tsa gago di bolokeletswe tshekatsheko ya motsamaisi. Bua le motsamaisi wa gago, mme o boeletse tlhatlhobo fa seemo sa gago se fetoga.",
  "You have not chosen a PIN yet. Sign in with your password once, then choose one.": "Ga o ise o tlhophe PIN. Tsena ka phasewete ya gago ga le nngwe, mme o tlhophe nngwe.",
  "You led": "Ke wena o eteletseng pele",
  "You made this request, so a second SystemAdmin decides it. You can withdraw it.": "Ke wena o dirileng kopo eno, ka jalo SystemAdmin wa bobedi o tsaya tshwetso ka yone. O ka e gogela morago.",
  "You may not open this camera.": "Ga o letlelelwe go bula khamera eno.",
  "You sign in with": "O tsena ka",
  "You use call signs when you give out duties.": "O dirisa maswao a pitso fa o aba ditiro.",
  "You were backup": "O ne o le thuso",
  "You will be called out when you are needed.": "O tla bidiwa fa o tlhokega.",
  "You will join as backup.": "O tla tsena jaaka thuso.",
  "You will lead this incident.": "O tla eteletsa tiragalo eno pele.",
  "You will not be cleared until this is restocked": "O ka se letlelelwe go fitlha se se tlatswa gape",
  "You will print a slip with a one-time code and hand it to {first} in person. They sign in with{value}.": "O tla gatisa setlankana se se nang le khoutu ya ga le nngwe mme o se neele {first} ka seatla. Ba tsena ka{value}.",
  "You, {ago}": "Wena, {ago}",
  "Your PIN is locked after 5 wrong tries. Enter your password to choose a new one.": "PIN ya gago e notletswe morago ga maiteko a le 5 a a phoso. Tsenya phasewete ya gago go tlhopha e ntšhwa.",
  "Your PIN is locked after 5 wrong tries. Sign in with your password and choose a new PIN, or ask your supervisor to unlock it.": "PIN ya gago e notletswe morago ga maiteko a le 5 a a phoso. Tsena ka phasewete ya gago mme o tlhophe PIN e ntšhwa, kgotsa o kope motsamaisi wa gago gore a e notlolole.",
  "Your PIN is set": "PIN ya gago e tlhomilwe",
  "Your SOS — dispatch is sending help to you": "SOS ya gago — baromedi ba romela thuso kwa go wena",
  "Your SOS — help is being sent": "SOS ya gago — thuso e a romelwa",
  "Your account is ready": "Akhaonto ya gago e siametse",
  "Your arrival is not confirmed yet. It confirms itself when your phone shows you at the scene, or ask dispatch to confirm it. Then file the report.": "Go goroga ga gago ga go ise go netefadiwe. Go tla itlhomamisa fa founu ya gago e go bontsha o le kwa lefelong, kgotsa o kope baromedi gore ba go netefatse. Mme o romele pego.",
  "Your badge number": "Nomore ya gago ya beche",
  "Your balances": "Dipalanse tsa gago",
  "Your camera and microphone are live.": "Khamera le maekerofouno ya gago di a dira ka nako ya nnete.",
  "Your checks are complete.": "Ditlhatlhobo tsa gago di weditswe.",
  "Your department was stood down.": "Lefapha la gago le emisitswe.",
  "Your duty status will be cleared.": "Seemo sa gago sa tiro se tla phimolwa.",
  "Your email address or badge number": "Aterese ya gago ya imeile kgotsa nomore ya beche",
  "Your figures this month": "Dipalo tsa gago mo kgweding eno",
