  "Your hard hat": "Kepisi ya gago ya tshireletso",
  "Your incidents, live. Respond and advance status as things happen.": "Ditiragalo tsa gago, ka nako ya nnete. Araba mme o tswelele seemo pele fa dilo di diragala.",
  "Your kit could not be checked. You can still try to end the shift.": "Didirisiwa tsa gago ga di a kgona go tlhatlhobiwa. O sa ntse o ka leka go fetsa šifiti.",
  "Your last check ({ref}) found stock short: {items}. Restock, tick what is now on board and file again.": "Tlhatlhobo ya gago ya bofelo ({ref}) e fitlhetse gore dithoto di a tlhaela: {items}. Tlatsa gape, tshwaya se se mo koloing jaanong mme o romele gape.",
  "Your location could not be found. Type the address.": "Lefelo la gago ga le a bonwa. Kwala aterese.",
  "Your next shift": "Šifiti ya gago e e latelang",
  "Your operational throughput vs the team, plus your annual appraisal ({cycleLabel}).": "Tiro ya gago ya tirelo go bapisiwa le setlhopha, mmogo le tlhatlhobo ya gago ya ngwaga ({cycleLabel}).",
  "Your password": "Phasewete ya gago",
  "Your patient report is on record.": "Pego ya gago ya molwetse e mo rekotong.",
