  "Your readiness declaration is on record. You are not cleared to go on duty. Contact your shift supervisor before continuing.": "Kanegelo ya gago ya go ipaakanya e mo rekotong. Ga o letlelelwe go tsena mo tirong. Ikgolaganye le motsamaisi wa šifiti ya gago pele o tswelela.",
  "Your readiness declaration is on record. You are not cleared to go on duty. Contact your station officer or supervisor before continuing.": "Kanegelo ya gago ya go ipaakanya e mo rekotong. Ga o letlelelwe go tsena mo tirong. Ikgolaganye le mohlankedi wa seteišene sa gago kgotsa motsamaisi pele o tswelela.",
